using Payments;

namespace PaymentGateway.Tests;

[TestClass]
public sealed class PaymentGatewayChargeTests
{
    private readonly Payments.PaymentGateway _gateway;

    public PaymentGatewayChargeTests()
    {
        _gateway = new Payments.PaymentGateway();
    }

    [TestMethod]
    public async Task ChargeAsync_WithValidCardAndAmount_ReturnsSuccess()
    {
        // Arrange
        var cardToken = "tok_valid_visa";
        var amount = 49.99m;

        // Act
        var result = await _gateway.ChargeAsync(cardToken, amount);

        // Assert
        Assert.IsNotNull(result);
        Assert.IsTrue(result.Success);
        Assert.IsNotNull(result.ChargeId);
    }

    [TestMethod]
    public async Task ChargeAsync_WithValidCard_ReturnsNonEmptyChargeId()
    {
        // Act
        var result = await _gateway.ChargeAsync("tok_valid_visa", 100m);

        // Assert
        Assert.IsNotNull(result.ChargeId);
        Assert.AreNotEqual(string.Empty, result.ChargeId);
    }

    [TestMethod]
    [DataRow("")]
    [DataRow(null)]
    public async Task ChargeAsync_WithNullOrEmptyToken_ThrowsArgumentException(string? cardToken)
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync(cardToken!, 10m));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    [DataRow(-100.50)]
    public async Task ChargeAsync_WithZeroOrNegativeAmount_ThrowsArgumentOutOfRangeException(double amount)
    {
        await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_valid", (decimal)amount));
    }

    [TestMethod]
    public async Task ChargeAsync_WithDeclinedCard_ReturnsFailure()
    {
        // Arrange
        var cardToken = "tok_declined";

        // Act
        var result = await _gateway.ChargeAsync(cardToken, 50m);

        // Assert
        Assert.IsNotNull(result);
        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    [DataRow(0.01, DisplayName = "Minimum charge")]
    [DataRow(9999.99, DisplayName = "Large charge")]
    [DataRow(1.00, DisplayName = "One dollar")]
    public async Task ChargeAsync_WithVariousValidAmounts_ReturnsSuccess(double amount)
    {
        var result = await _gateway.ChargeAsync("tok_valid_visa", (decimal)amount);

        Assert.IsTrue(result.Success);
    }
}

[TestClass]
public sealed class PaymentGatewayRefundTests
{
    private readonly Payments.PaymentGateway _gateway;

    public PaymentGatewayRefundTests()
    {
        _gateway = new Payments.PaymentGateway();
    }

    [TestMethod]
    public async Task RefundAsync_WithValidChargeId_ReturnsSuccess()
    {
        // Arrange
        var chargeId = "ch_valid_123";

        // Act
        var result = await _gateway.RefundAsync(chargeId);

        // Assert
        Assert.IsNotNull(result);
        Assert.IsTrue(result.Success);
        Assert.IsNotNull(result.RefundId);
    }

    [TestMethod]
    public async Task RefundAsync_WithValidChargeId_ReturnsNonEmptyRefundId()
    {
        var result = await _gateway.RefundAsync("ch_valid_123");

        Assert.IsNotNull(result.RefundId);
        Assert.AreNotEqual(string.Empty, result.RefundId);
    }

    [TestMethod]
    [DataRow("")]
    [DataRow(null)]
    public async Task RefundAsync_WithNullOrEmptyChargeId_ThrowsArgumentException(string? chargeId)
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.RefundAsync(chargeId!));
    }

    [TestMethod]
    public async Task RefundAsync_WithNonExistentChargeId_ReturnsFailure()
    {
        var result = await _gateway.RefundAsync("ch_nonexistent");

        Assert.IsNotNull(result);
        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    public async Task RefundAsync_WithAlreadyRefundedCharge_ReturnsFailure()
    {
        var result = await _gateway.RefundAsync("ch_already_refunded");

        Assert.IsNotNull(result);
        Assert.IsFalse(result.Success);
    }
}

